import os, json, numpy as np

IN_JSON = 'storage/shared/agents/zephyr/ven_ridge_analysis.json'
OUT_DIR = 'storage/shared/agents/kairos/VEN/tables'
os.makedirs(OUT_DIR, exist_ok=True)

def deep_items(obj, path=()):
    if isinstance(obj, dict):
        for k, v in obj.items():
            yield from deep_items(v, path + (str(k),))
    elif isinstance(obj, (list, tuple)):
        for i, v in enumerate(obj):
            yield from deep_items(v, path + (f"[{i}]",))
    else:
        yield path, obj

def find_arrays(d, modes=('balanced','discovery','grounded')):
    out = {m: [] for m in modes}
    for path, v in deep_items(d):
        if isinstance(v, list) and v and isinstance(v[0], (list, tuple)):
            flat = ".".join(path).lower()
            for m in modes:
                if m in flat:
                    out[m].append(v)
    return out

def find_axis(d, keys=('alpha','ratio','r','x','y')):
    for k in keys:
        for path, v in deep_items(d):
            flat = ".".join(path).lower()
            if k in flat and isinstance(v, list) and v and not isinstance(v[0], (list, tuple)):
                try:
                    return [float(x) for x in v], k
                except Exception:
                    continue
    return None, None

def best_array(arrs):
    return max(arrs, key=lambda a: len(a)*len(a[0])) if arrs else None

with open(IN_JSON, 'r', encoding='utf-8') as f:
    data = json.load(f)

arrays = find_arrays(data)
r_axis, r_key = find_axis(data, ('ratio','r','x'))
a_axis, a_key = find_axis(data, ('alpha','y'))

# Mode table
table_csv = os.path.join(OUT_DIR, 'ven_ridge_mode_table.csv')
with open(table_csv, 'w', encoding='utf-8') as f:
    f.write('mode,max,mean,ridge_count,total,frac_ridge,threshold\n')
    for mode in ('balanced','discovery','grounded'):
        arr = best_array(arrays.get(mode, []))
        if arr is None:
            f.write(f"{mode},,,,,0,0.75\n")
            continue
        Z = np.array(arr, dtype=float)
        thr = 0.75
        ridge = np.sum(Z >= thr)
        f.write(f"{mode},{float(np.nanmax(Z))},{float(np.nanmean(Z))},{int(ridge)},{int(Z.size)},{float(ridge/Z.size if Z.size else 0.0)},0.75\n")

# Contour summary
contours_txt = os.path.join(OUT_DIR, 'ven_ridge_contours_summary.txt')
with open(contours_txt, 'w', encoding='utf-8') as f:
    f.write("VEN ridge contour summary (argmax and ridge fraction >=0.75)\n")
    f.write(f"axes: {a_key} (rows), {r_key} (cols)\n")
    for mode in ('balanced','discovery','grounded'):
        arr = best_array(arrays.get(mode, []))
        if arr is None:
            f.write(f"- {mode}: no arrays found\n")
            continue
        Z = np.array(arr, dtype=float)
        i, j = np.unravel_index(np.nanargmax(Z), Z.shape)
        r_val = r_axis[j] if (isinstance(r_axis, list) and j < len(r_axis)) else None
        a_val = a_axis[i] if (isinstance(a_axis, list) and i < len(a_axis)) else None
        ridge_frac = float(np.sum(Z >= 0.75)/Z.size) if Z.size else 0.0
        f.write(f"- {mode}: max={float(np.nanmax(Z)):.4f} at (row={i}, col={j}) -> ({a_key}={a_val}, {r_key}={r_val}); ridge_frac>=0.75={ridge_frac:.3f}\n")

print(f"[artifacts] {table_csv} | {contours_txt}")
